#!/usr/bin/env bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-08-08

# tests/unit/test-semver-compare.sh
#
# Pins scripts/lib/semver.sh against the semver 2.0.0 precedence rules the
# release rails depend on.
#
# The point of this file is the platform split. `sort -V` gets prerelease
# ordering backwards, and the fix leans on `~` sorting before the empty string,
# which is Debian ordering rather than anything semver guarantees. That property
# holds today on GNU coreutils 9.7 and on Apple's sort 2.3, but it is an
# implementation detail of the sort we happen to call. Running the same table on
# whichever platform executes this suite is what turns "it worked when I checked"
# into a standing check: CI runs it on Linux, the pre-push hook runs it on macOS.
#
# Every match below uses `[[ =~ ]]` rather than `printf | grep -q`. That is not
# style: under `set -o pipefail` grep -q exits at its first match, the producer
# dies on SIGPIPE, and the pipeline returns 141, which flips the enclosing `if`
# non-deterministically (#603). `[[ =~ ]]` runs no subprocess at all.

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PROJECT_ROOT="${CLAUDE_PROJECT_DIR:-$(cd "$SCRIPT_DIR/../.." && pwd)}"

# shellcheck source=/dev/null
. "$PROJECT_ROOT/scripts/lib/semver.sh"

RED=$'\033[0;31m'; GREEN=$'\033[0;32m'; NC=$'\033[0m'
PASS=0; FAIL=0

ok()  { echo "  ${GREEN}✓${NC} $1"; PASS=$((PASS + 1)); }
bad() { echo "  ${RED}✗${NC} $1"; FAIL=$((FAIL + 1)); }

# Report which sort is under test. `--version` is a GNU extension; BSD sort
# rejects it, and that non-zero status is the answer rather than an error, so
# it is read explicitly instead of being discarded.
sort_impl() {
    local out
    if out="$(sort --version 2>&1)"; then
        printf '%s\n' "$out" | head -1
    else
        printf 'BSD sort (no --version)\n'
    fi
}

echo "=========================================="
echo "  semver comparison"
echo "  under: $(sort_impl)"
echo "=========================================="
echo ""

# --------------------------------------------------------------------------
# 1. Precedence. Left side is strictly lower in every pair.
# --------------------------------------------------------------------------
echo "▶ Precedence: lower | higher"
echo "──────────────────────────────────────"

# The first three pairs are the ones plain `sort -V` gets WRONG. If someone
# reverts the helper to a bare `sort -V`, those fail and the rest pass, which
# names the regression precisely instead of just going red.
PAIRS="
10.0.0-alpha.1|10.0.0
10.0.0-rc.1|10.0.0
1.0.0-alpha|1.0.0
9.8.0|10.0.0
10.0.0-alpha.1|10.0.0-alpha.2
10.0.0-alpha.2|10.0.0-beta.1
10.0.0-beta.1|10.0.0-rc.1
9.8.0|10.0.0-alpha.1
1.0.0-alpha|1.0.0-alpha.1
"

while IFS='|' read -r lo hi; do
    [ -n "$lo" ] || continue

    got="$(semver_max "$lo" "$hi")"
    if [ "$got" = "$hi" ]; then
        ok "$lo < $hi"
    else
        bad "$lo < $hi — semver_max returned '$got'"
    fi

    if ! semver_lt "$lo" "$hi"; then bad "semver_lt $lo $hi should be true"; fi
    if ! semver_gt "$hi" "$lo"; then bad "semver_gt $hi $lo should be true"; fi
    if semver_lt "$hi" "$lo"; then bad "semver_lt $hi $lo must be false"; fi
done < <(printf '%s\n' "$PAIRS")

echo ""

# --------------------------------------------------------------------------
# 2. Equality is not strict-anything, and max is order independent.
# --------------------------------------------------------------------------
echo "▶ Equality and symmetry"
echo "──────────────────────────────────────"

for v in 9.8.0 10.0.0-alpha.1 1.0.0-alpha+build.5; do
    if [ "$(semver_max "$v" "$v")" = "$v" ]; then
        ok "max($v,$v) = $v"
    else
        bad "max($v,$v) returned something else"
    fi
    if semver_lt "$v" "$v"; then bad "semver_lt $v $v must be false"; fi
    if semver_gt "$v" "$v"; then bad "semver_gt $v $v must be false"; fi
done

# Argument order must not decide the winner.
a="$(semver_max 10.0.0 10.0.0-alpha.1)"
b="$(semver_max 10.0.0-alpha.1 10.0.0)"
if [ "$a" = "$b" ]; then
    ok "max is order independent ($a)"
else
    bad "order dependent: $a vs $b"
fi

echo ""

# --------------------------------------------------------------------------
# 3. Core / prerelease split.
# --------------------------------------------------------------------------
echo "▶ Core and prerelease detection"
echo "──────────────────────────────────────"

check_core() {
    local got
    got="$(semver_core "$1")"
    if [ "$got" = "$2" ]; then
        ok "core($1) = $2"
    else
        bad "core($1) = '$got', want '$2'"
    fi
}
check_core 10.0.0 10.0.0
check_core 10.0.0-alpha.1 10.0.0
check_core 1.0.0+build.5 1.0.0
check_core 1.0.0-alpha+build.5 1.0.0

if semver_is_prerelease 10.0.0-alpha.1; then
    ok "10.0.0-alpha.1 is a prerelease"
else
    bad "10.0.0-alpha.1 not detected as a prerelease"
fi
if semver_is_prerelease 10.0.0; then
    bad "10.0.0 wrongly detected as a prerelease"
else
    ok "10.0.0 is not a prerelease"
fi
# A '-' inside build metadata is not a prerelease marker.
if semver_is_prerelease '1.0.0+build-5'; then
    bad "build metadata read as a prerelease"
else
    ok "1.0.0+build-5 is not a prerelease"
fi

echo ""

# --------------------------------------------------------------------------
# 4. Regex escaping. A version is data, never a pattern.
# --------------------------------------------------------------------------
echo "▶ Regex escaping"
echo "──────────────────────────────────────"

esc="$(semver_regex_escape '1.0.0+build.5')"
if [[ "1.0.0+build.5" =~ ^${esc}$ ]]; then
    ok "escaped version matches itself"
else
    bad "escaped version does not match itself (esc='$esc')"
fi

# The whole point: left unescaped, those dots are wildcards. Asserting the bug
# exists keeps this test honest — if a future bash stopped treating '.' as a
# metacharacter, the escaping test below would pass for the wrong reason.
if [[ "10x0x0" =~ ^10.0.0$ ]]; then
    ok "unescaped 10.0.0 does match 10x0x0 (the bug being fixed)"
else
    bad "expected unescaped dots to be wildcards; bash behaved unexpectedly"
fi

esc_plain="$(semver_regex_escape 10.0.0)"
if [[ "10x0x0" =~ ^${esc_plain}$ ]]; then
    bad "escaped 10.0.0 wrongly matched 10x0x0"
else
    ok "escaped 10.0.0 does not match 10x0x0"
fi

echo ""
echo "=========================================="
echo "  Results: ${PASS} passed, ${FAIL} failed"
echo "=========================================="

[ "$FAIL" -eq 0 ] || exit 1
